Object.assign(SNIP,{"l24ops": "vector<int> v;\nv.push_back(10);      // thêm vào cuối: {10}\nv.push_back(20);      // {10, 20}\nv.size();             // 2\nv[0];                 // 10   (giống mảng)\nv.back();             // 20   (phần tử cuối)\nv.pop_back();         // bỏ phần tử cuối: {10}\nv.empty();            // false\nv.clear();            // xóa hết: {}\nv.resize(3);          // {0, 0, 0}", "l24decl": "vector<int> a;                 // rỗng, size = 0\nvector<int> b(5);              // 5 phần tử, đều bằng 0\nvector<int> c(5, -1);          // 5 phần tử, đều bằng -1\nvector<int> d = {3, 1, 4};     // liệt kê\nvector<string> ten = {\"An\", \"Binh\"};\nvector<vector<int>> g(3, vector<int>(4, 0));   // bảng 3 hàng × 4 cột toàn 0", "l24func": "// đọc: const & (không chép, không sửa)      sửa: &          trả về: vector mới\nlong long tong(const vector<int>& v) { long long s = 0; for (int x : v) s += x; return s; }\nvoid tangMot(vector<int>& v) { for (int& x : v) x++; }\nvector<int> soChan(const vector<int>& v) {\n    vector<int> kq;\n    for (int x : v) if (x % 2 == 0) kq.push_back(x);\n    return kq;\n}"});PRESET_NOTES["l24"]={"Ví dụ: push_back khi đọc dữ liệu": "vector bắt đầu rỗng; mỗi push_back thêm một ô vào cuối và size tăng 1. v.back() là phần tử cuối.", "Ví dụ: Duyệt bằng bản sao và bằng tham chiếu": "Vòng đầu x là bản sao nên v không đổi. Vòng sau x là tham chiếu (int&) tới từng phần tử: khung Bộ nhớ ghi x ↔ v[i], và v được nhân 10.", "Ví dụ: pop_back, back, empty": "Lấy phần tử cuối rồi bỏ nó đi, lặp tới khi rỗng: thứ tự lấy ra ngược với thứ tự thêm vào (giống chồng đĩa, sẽ gặp lại ở cấu trúc ngăn xếp).", "Ví dụ: Lọc số chẵn sang vector mới": "Hàm nhận const vector<int>& (không chép, không sửa) và trả về một vector mới. Không biết trước có bao nhiêu số chẵn, nên dùng push_back.", "Ví dụ: sort và reverse": "sort sắp tăng dần cả đoạn [v.begin(), v.end()). reverse đảo ngược. greater<int>() làm sort sắp giảm dần.", "Ví dụ: Bảng bằng vector<vector<int>>": "Một vector gồm n vector con, mỗi vector con m phần tử. Kích thước n, m có thể là biến đọc lúc chạy, điều mảng tĩnh không làm được.", "Lỗi: gán v[0] khi vector rỗng": "vector rỗng chưa có ô nào nên không có v[0]. Sửa: v.push_back(5); hoặc tạo trước vector<int> v(1);.", "Bẫy: v.size() - 1 với vector rỗng": "size() không dấu nên 0 - 1 thành 18446744073709551615: điều kiện i <= v.size() - 1 đúng và chương trình đọc v[0] không tồn tại. g++ còn cảnh báo so sánh có dấu/không dấu. Viết i < v.size()."};EX_HINTS["l24"]=[["Số âm chia hết cho 2 cũng là số chẵn: x % 2 == 0 đúng cả với -2 (trong C++, -3 % 2 là -1, nên đừng viết x % 2 == 1 để kiểm tra số lẻ).", "Không biết trước bao nhiêu số chẵn: dùng vector rỗng và push_back."], ["Giữ vector kq chứa các số đã gặp. Mỗi số mới, duyệt kq xem đã có chưa.", "Đặt cờ bool daCo = false trước vòng kiểm tra; gặp số bằng x thì đặt true và break."], ["Hai chỉ số i (trên a) và j (trên b). Mỗi bước so sánh a[i] với b[j], đưa số nhỏ hơn vào kết quả và tiến chỉ số tương ứng.", "Khi một dãy đã hết, chép nốt phần còn lại của dãy kia.", "Cách này chỉ cần n + m bước; đây chính là bước trộn của thuật toán sắp xếp trộn (merge sort)."]];
/* ===================== BÀI 24 · vector cơ bản ===================== */
/* Bài 24 · vector cơ bản
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P24=[{label:"Ví dụ: push_back khi đọc dữ liệu",input:"5\n7 3 9 1 4",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> v;\n    for (int i = 0; i < n; i++) {\n        int x;\n        cin >> x;\n        v.push_back(x);\n    }\n    cout << \"So phan tu: \" << v.size() << \"\\n\";\n    cout << \"Dau: \" << v[0] << \", cuoi: \" << v.back() << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"v"}]},{label:"Ví dụ: Duyệt bằng bản sao và bằng tham chiếu",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {1, 2, 3};\n    for (int x : v) {\n        x = x * 10;\n    }\n    cout << v[0] << \" \" << v[1] << \" \" << v[2] << \"\\n\";\n    for (int& x : v) {\n        x = x * 10;\n    }\n    cout << v[0] << \" \" << v[1] << \" \" << v[2] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"v"}]},{label:"Ví dụ: pop_back, back, empty",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {4, 8, 15};\n    while (!v.empty()) {\n        cout << \"Lay ra \" << v.back() << \"\\n\";\n        v.pop_back();\n    }\n    cout << \"Con lai \" << v.size() << \" phan tu\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"v"}]},{label:"Ví dụ: Lọc số chẵn sang vector mới",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nvector<int> soChan(const vector<int>& v) {\n    vector<int> kq;\n    for (int x : v) {\n        if (x % 2 == 0) kq.push_back(x);\n    }\n    return kq;\n}\n\nint main() {\n    vector<int> a = {5, 8, 2, 7, 10, 3};\n    vector<int> c = soChan(a);\n    for (int x : c) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a"},{type:"cells",of:"kq"}]},{label:"Ví dụ: sort và reverse",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<int> v = {5, 2, 9, 1, 7};\n    sort(v.begin(), v.end());\n    for (int x : v) cout << x << \" \";\n    cout << \"\\n\";\n    reverse(v.begin(), v.end());\n    for (int x : v) cout << x << \" \";\n    cout << \"\\n\";\n    sort(v.begin(), v.end(), greater<int>());\n    cout << v[0] << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"v"}]},{label:"Ví dụ: Bảng bằng vector<vector<int>>",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n = 3, m = 4;\n    vector<vector<int>> g(n, vector<int>(m, 0));\n    for (int i = 0; i < n; i++)\n        for (int j = 0; j < m; j++)\n            g[i][j] = i * m + j;\n    cout << g[2][3] << \" \" << g.size() << \" \" << g[0].size() << \"\\n\";\n    return 0;\n}",viz:[{type:"grid",of:"g",cur:["i","j"]}]},{label:"Lỗi: gán v[0] khi vector rỗng",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v;\n    v[0] = 5;\n    cout << v[0] << \"\\n\";\n    return 0;\n}"},{label:"Bẫy: v.size() - 1 với vector rỗng",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v;\n    cout << v.size() - 1 << \"\\n\";\n    for (int i = 0; i <= v.size() - 1; i++) {\n        cout << v[i] << \"\\n\";\n    }\n    return 0;\n}"}];
const sim24=makeSim2(document.getElementById("sim-l24"),{id:"s24",presets:P24});
makeEx2(document.getElementById("ex-l24"),sim24,[{t:"Các số chẵn",d:"Nhập n rồi n số nguyên. Dòng 1 in số lượng số chẵn. Dòng 2 in các số chẵn theo thứ tự xuất hiện, cách nhau một dấu cách (in dòng trống nếu không có số chẵn).",tests:[{in:"6\n5 8 2 7 10 3",out:"3\n8 2 10"},{in:"3\n1 3 5",out:"0\n"},{in:"4\n0 -2 4 -6",out:"4\n0 -2 4 -6"},{in:"1\n2",out:"1\n2"}],start:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> chan;\n    // đọc từng số, số chẵn thì push_back\n    return 0;\n}"},{t:"Bỏ phần tử trùng lặp",d:"Nhập n (1 ≤ n ≤ 1000) rồi n số nguyên. In dãy sau khi bỏ các phần tử trùng, chỉ giữ lần xuất hiện đầu tiên và giữ nguyên thứ tự.",tests:[{in:"7\n3 1 3 2 1 5 3",out:"3 1 2 5"},{in:"1\n4",out:"4"},{in:"5\n9 9 9 9 9",out:"9"},{in:"6\n1 2 3 4 5 6",out:"1 2 3 4 5 6"},{in:"4\n-1 0 -1 0",out:"-1 0"}],start:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> kq;\n    // với mỗi x: nếu chưa có trong kq thì thêm vào\n    return 0;\n}"},{t:"Trộn hai dãy tăng dần",d:"Nhập n và dãy a gồm n số đã sắp tăng dần, rồi m và dãy b gồm m số tăng dần. In dãy gồm tất cả n + m số, sắp tăng dần. Không dùng sort: hãy đi song song trên hai dãy (n, m ≤ 1000).",tests:[{in:"3\n1 4 9\n4\n2 3 10 11",out:"1 2 3 4 9 10 11"},{in:"1\n5\n1\n5",out:"5 5"},{in:"2\n1 2\n0\n",out:"1 2"},{in:"3\n-5 0 5\n2\n-6 6",out:"-6 -5 0 5 6"}],start:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n;\n    vector<int> a(n);\n    for (int& x : a) cin >> x;\n    cin >> m;\n    vector<int> b(m);\n    for (int& x : b) cin >> x;\n    // i chạy trên a, j chạy trên b: mỗi bước lấy số nhỏ hơn\n    return 0;\n}",need:/^(?![\s\S]*\bsort\s*\()/,needMsg:"Bài này luyện cách trộn hai dãy: hãy làm mà không dùng sort."}]);

makeQuiz("quiz24","score24",[{"q": "Sau <code>vector&lt;int&gt; v(3, 7); v.push_back(1);<\/code> thì <code>v.size()<\/code> và <code>v.back()<\/code> là?", "o": ["3 và 7", "4 và 1", "4 và 7", "1 và 1"], "a": 1, "e": "v(3, 7) có 3 phần tử bằng 7; push_back thêm phần tử thứ tư là 1 vào cuối."}, {"q": "Vòng lặp nào nhân đôi mọi phần tử của <code>v<\/code>?", "o": ["<code>for (int x : v) x *= 2;<\/code>", "<code>for (int&amp; x : v) x *= 2;<\/code>", "<code>for (const int&amp; x : v) x *= 2;<\/code>", "Cả ba"], "a": 1, "e": "Chỉ int& x là tham chiếu tới phần tử; int x là bản sao, const int& thì không được sửa (lỗi biên dịch)."}, {"q": "Hàm chỉ cần đọc một vector lớn nên khai báo tham số thế nào?", "o": ["<code>vector&lt;int&gt; v<\/code>", "<code>vector&lt;int&gt;&amp; v<\/code>", "<code>const vector&lt;int&gt;&amp; v<\/code>", "<code>int v[]<\/code>"], "a": 2, "e": "const & không chép vector (nhanh) và bảo đảm hàm không sửa nó."}, {"q": "<code>vector&lt;int&gt; v;<\/code> (rỗng). Giá trị của <code>v.size() - 1<\/code>?", "o": ["-1", "0", "Một số dương rất lớn", "Lỗi biên dịch"], "a": 2, "e": "size() trả về size_t (không dấu); 0 - 1 quay vòng thành 18446744073709551615."}]);

